// Schritt 1: Adressen sammeln und Typ markieren
const items = $input.all();
const addressItems = [];

for (const item of items) {
  const data = item.json;

  // UNTERSCHEIDUNG: Kandidaten haben property_geburtsdatum, Fachgeschäfte nicht!

  // Kandidaten - haben Geburtsdatum (sind Personen) UND wohnadresse
  if (data.property_geburtsdatum && data.property_wohnadresse && data.property_wohnadresse.trim() !== '') {
    addressItems.push({
      json: {
        id: data.id,
        name: data.property_name,
        phone: data.property_handynummer || null,
        address: data.property_wohnadresse,
        type: 'kandidat'
      }
    });
  }
  // Fachgeschäfte - haben KEIN Geburtsdatum (sind Geschäfte) ABER property_adresse
  else if (!data.property_geburtsdatum && data.property_adresse && data.property_adresse.trim() !== '') {
    addressItems.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        type: 'fachgeschaeft'
      }
    });
  }
}

console.log(`Extrahiert: ${addressItems.filter(i => i.json.type === 'kandidat').length} Kandidaten, ${addressItems.filter(i => i.json.type === 'fachgeschaeft').length} Fachgeschäfte`);

return addressItems;

// Koordinaten aus API-Response extrahieren
const item = $input.first();
const response = item.json;

if (response.status === 'OK' && response.results && response.results.length > 0) {
  const location = response.results[0].geometry.location;

  return [{
    json: {
      id: $('📍 Adressen extrahieren').item.json.id,
      name: $('📍 Adressen extrahieren').item.json.name,
      phone: $('📍 Adressen extrahieren').item.json.phone,
      address: $('📍 Adressen extrahieren').item.json.address,
      type: $('📍 Adressen extrahieren').item.json.type,
      lat: location.lat,
      lng: location.lng,
      geocoded: true
    }
  }];
} else {
  return [{
    json: {
      id: $('📍 Adressen extrahieren').item.json.id,
      name: $('📍 Adressen extrahieren').item.json.name,
      phone: $('📍 Adressen extrahieren').item.json.phone,
      address: $('📍 Adressen extrahieren').item.json.address,
      type: $('📍 Adressen extrahieren').item.json.type,
      geocoded: false
    }
  }];
}

// Zuordnung mit MIN und MAX Distanz
const allItems = $input.first().json.data;

// Distanz-Bereich (hier anpassen!)
const minDistanzKm = 10;
const maxDistanzKm = 100;

console.log("=== DISTANZ-BEREICH ===");
console.log(`Min: ${minDistanzKm} km, Max: ${maxDistanzKm} km`);

// Kandidaten und Fachgeschäfte trennen
const kandidaten = allItems.filter(item => item.type === 'kandidat' && item.geocoded);
const fachgeschaefte = allItems.filter(item => item.type === 'fachgeschaeft' && item.geocoded);

console.log(`\nKandidaten: ${kandidaten.length}`);
console.log(`Fachgeschäfte: ${fachgeschaefte.length}`);

if (kandidaten.length === 0 || fachgeschaefte.length === 0) {
  return [{
    json: {
      error: 'Keine gültigen Kandidaten oder Fachgeschäfte gefunden',
      kandidaten_count: kandidaten.length,
      fachgeschaefte_count: fachgeschaefte.length
    }
  }];
}

// Haversine-Formel
function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

// Zuordnungen berechnen MIT MIN/MAX Filter
const ergebnisse = [];

for (const kandidat of kandidaten) {
  const naheGeschafte = [];

  for (const geschaeft of fachgeschaefte) {
    const distanz = calculateDistance(
      kandidat.lat,
      kandidat.lng,
      geschaeft.lat,
      geschaeft.lng
    );

    const distanzGerundet = Math.round(distanz * 10) / 10;

    // MIN und MAX Distanz prüfen
    if (distanz >= minDistanzKm && distanz <= maxDistanzKm) {
      naheGeschafte.push({
        id: geschaeft.id,
        name: geschaeft.name,
        distanz: distanzGerundet
      });
    }
  }

  // Sortiere nach Distanz (nächstes zuerst)
  naheGeschafte.sort((a, b) => a.distanz - b.distanz);

  if (naheGeschafte.length > 0) {
    ergebnisse.push({
      json: {
        kandidat_id: kandidat.id,
        kandidat_name: kandidat.name,
        kandidat_phone: kandidat.phone,
        fachgeschaefte_ids: naheGeschafte.map(g => g.id),
        fachgeschaefte_namen: naheGeschafte.map(g => g.name),
        distanzen_km: naheGeschafte.map(g => g.distanz),
        anzahl: naheGeschafte.length,
        naechstes_geschaeft: naheGeschafte[0].name,
        naechste_distanz_km: naheGeschafte[0].distanz
      }
    });
  }
}

console.log(`\n${ergebnisse.length} Kandidaten im Distanz-Bereich ${minDistanzKm}-${maxDistanzKm} km`);

if (ergebnisse.length === 0) {
  return [{
    json: {
      info: 'Keine Kandidaten im angegebenen Distanz-Bereich gefunden',
      min_distanz_km: minDistanzKm,
      max_distanz_km: maxDistanzKm,
      kandidaten_count: kandidaten.length,
      fachgeschaefte_count: fachgeschaefte.length
    }
  }];
}

return ergebnisse;

